package main

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	// Template for rendering user profile
	tmpl = template.Must(template.New("profile").Parse(`
<html><body>
<h1>User Profile</h1>
<div class="username">{{.Username}}</div>
<div class="bio">{{.Bio}}</div>
<div class="avatar"><img src="{{.AvatarURL}}"></div>
</body></html>`))
}

type Profile struct {
	Username  string
	Bio       string
	AvatarURL string
}

func hashToken(token string) string {
	h := sha256.Sum256([]byte(token))
	return hex.EncodeToString(h[:])
}

// updateBio allows users to update their bio field
func updateBio(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	sessionToken := r.Header.Get("X-Session-Token")
	if sessionToken == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	// Validate session - get user_id from sessions table
	tokenHash := hashToken(sessionToken)
	var userID int
	err := db.QueryRow("SELECT user_id FROM sessions WHERE token_hash = $1 AND expires_at > NOW()", tokenHash).Scan(&userID)
	if err != nil {
		http.Error(w, "Invalid session", 401)
		return
	}

	newBio := r.FormValue("bio")
	// Basic length check
	if len(newBio) > 500 {
		http.Error(w, "Bio too long", 400)
		return
	}

	// Sanitize: strip script tags (basic XSS prevention)
	newBio = strings.ReplaceAll(newBio, "<script", "")
	newBio = strings.ReplaceAll(newBio, "</script", "")

	// Update bio in database
	_, err = db.Exec("UPDATE users SET bio = $1 WHERE id = $2", newBio, userID)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}

	w.WriteHeader(200)
	w.Write([]byte("Bio updated"))
}

// viewProfile renders a user's profile page
func viewProfile(w http.ResponseWriter, r *http.Request) {
	username := r.URL.Query().Get("user")
	if username == "" {
		http.Error(w, "Missing user parameter", 400)
		return
	}

	// Alphanumeric check on username for DB query safety
	for _, c := range username {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') {
			http.Error(w, "Invalid username", 400)
			return
		}
	}

	var p Profile
	err := db.QueryRow("SELECT username, bio, avatar_url FROM users WHERE username = $1", username).Scan(&p.Username, &p.Bio, &p.AvatarURL)
	if err != nil {
		http.Error(w, "User not found", 404)
		return
	}

	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, p)
}

func main() {
	http.HandleFunc("/profile", viewProfile)
	http.HandleFunc("/update-bio", updateBio)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
